    if 0 <= nr < 7 and 0 <= nc < 18:
        return nr, nc
    return None

def check_immediate_hit(nr, nc):
    for mr, mc in marker_coords:
        if mr == nr and mc == nc:
            return True
    return False

to_fill = []
for r_start, c_start, val in special:
    dirs = [(-1,-1), (-1,1), (1,-1), (1,1)]  # UL, UR, DL, DR

    for dr, dc in dirs:
        step = 1
        while True:
            pos = step_to(r_start, c_start, step, dr, dc)
            if pos is None:
                break
            nr, nc = pos
            if output_grid[nr][nc] != 9:
                break
            if check_immediate_hit(nr, nc):
                break
            output_grid[nr][nc] = val
            to_fill.append((nr, nc))
            step += 1

print(f"Pattern: Extend all diagonals from markers until edge/blocked/other marker")
print(f"Filled {len(to_fill)} cells:")
for t in to_fill:
    print(f"  {t}")
print("\nGrid:")
for row in output_grid:
    print(row)

action = json.dumps({"action": "submit", "grid": output_grid})
print("Action:", action[:120])
